function circlePath(r,n=128){const p=new THREE.Path();p.absarc(0,0,r,0,TAU,false);return p;}
export function ringGeometry(ro,ri,depth,holes=[]){const s=new THREE.Shape();s.absarc(0,0,ro,0,TAU,false);if(ri>0)s.holes.push(circlePath(ri));for(const [x,y,r] of holes){const h=new THREE.Path();h.absarc(x,y,r,0,TAU,false);s.holes.push(h);}const g=new THREE.ExtrudeGeometry(s,{depth,bevelEnabled:false,curveSegments:64,steps:1});g.translate(0,0,-depth/2);return g;}
export function cylinder(r1,r2,length,segments=64){const g=new THREE.CylinderGeometry(r1,r2,length,segments);g.rotateX(PI/2);return g;}
export function gearGeometry(teeth,pitch,depth,bore,internal=false){const m=2*pitch/teeth,root=pitch-1.25*m,tip=pitch+m,rb=pitch*Math.cos(20*PI/180),half=PI/(2*teeth);const inv=r=>{const u=Math.sqrt(Math.max(0,(r/rb)**2-1));return u-Math.atan(u)};const atPitch=inv(pitch);const pts=[];for(let i=0;i<teeth;i++){const center=i*TAU/teeth;pts.push([root,center-PI/teeth],[root,center-half-atPitch]);for(let k=0;k<=5;k++){const r=Math.max(root,rb)+(tip-Math.max(root,rb))*k/5;pts.push([r,center-half-atPitch+inv(r)]);}for(let k=5;k>=0;k--){const r=Math.max(root,rb)+(tip-Math.max(root,rb))*k/5;pts.push([r,center+half+atPitch-inv(r)]);}pts.push([root,center+half+atPitch],[root,center+PI/teeth]);}
 if(internal){const shape=new THREE.Shape();shape.absarc(0,0,pitch+.065,0,TAU,false);const p=new THREE.Path();pts.forEach(([r,a],i)=>{const rad=2*pitch-r;const x=rad*Math.cos(a),y=rad*Math.sin(a);i?p.lineTo(x,y):p.moveTo(x,y)});p.closePath();shape.holes.push(p);const g=new THREE.ExtrudeGeometry(shape,{depth,steps:1,bevelEnabled:false,curveSegments:96});g.translate(0,0,-depth/2);return g;}
 const shape=new THREE.Shape();pts.forEach(([r,a],i)=>{const x=r*Math.cos(a),y=r*Math.sin(a);i?shape.lineTo(x,y):shape.moveTo(x,y)});shape.closePath();shape.holes.push(circlePath(bore));const g=new THREE.ExtrudeGeometry(shape,{depth,steps:1,bevelEnabled:true,bevelSize:.0009,bevelThickness:.0009,bevelSegments:1,curveSegments:32});g.translate(0,0,-depth/2);return g;}
